---@param IBox IBox
function PersonalHomeView:OnClick(IBox)
    local  IBoxInfo= ExhibitBoxMgr:Get():GetBoxInfo(IBox:GetEntityID())
    local exhibitData =  PersonalHomeDataManager:Get():GetExhibitByServerID(IBoxInfo:GetDepositServerID())
    if exhibitData:GetType()==ExhibitType.Trophy then
        UIManager:Get():OpenPopup("ExhibitUseView", CanvasType.MainCanvas, "ExhibitUseView")
        UINotify:Get():SendNotification(UINotifyEvent.ExhibitViewSetData,{exhibitData,false})
    end
end

