---@param IBoxA IBox
---@param IBoxs IBox[]
function PersonalHomeView:Exchange(IBoxA,IBoxs)
    if self.curIBox~=IBoxA then
        return
    else
        self.curIBox=nil
    end
    ---@type ExhibitBoxInfo
    local  IBoxAInfo= ExhibitBoxMgr:Get():GetBoxInfo(IBoxA:GetEntityID())
    ---@type ExhibitBoxInfo
    local  IBoxBInfo
    ---@type IBox
    local IBoxB
    IBoxAInfo:Reset()
    if IBoxs~=nil then
        for i = 0, IBoxs.Count-1 do
            local  tempBox= ExhibitBoxMgr:Get():GetBoxInfo(IBoxs[i]:GetEntityID())
            if tempBox:GetType()==IBoxAInfo:GetType() then
                IBoxB = IBoxs[i]
                IBoxBInfo = tempBox
            end
        end
    end
    if IBoxBInfo==nil or IBoxB==nil then
        return
    end
    if PersonalHomeDataManager:Get():GetPersonalHomeData():GetRID()~=PlayerDataManager:Get():GetPlayerRID() then
        return
    end

    ---@type ExhibitData
    local exhibitDataA =  PersonalHomeDataManager:Get():GetExhibitByServerID(IBoxAInfo:GetDepositServerID())
    local exhibitDataB =  PersonalHomeDataManager:Get():GetExhibitByServerID(IBoxBInfo:GetDepositServerID())
    ---@type ExhibitBuilder
    local exhibitBuilderA,exhibitBuilderB
    if exhibitDataA then
        exhibitBuilderA = ExhibitBuilderManager:Get():GetBuilderById(exhibitDataA:GetExhibitBuilderId())
    end
    if exhibitDataB then
        exhibitBuilderB =  ExhibitBuilderManager:Get():GetBuilderById(exhibitDataB:GetExhibitBuilderId())
    end

    if PersonalHomeDataManager:Get():IsCanUpdateExhibitNode(exhibitDataA,exhibitDataA:GetParentServerID(),IBoxBInfo:GetSlotID()) then
        IBoxBInfo:SetDepositServerID(exhibitDataA:GetServerID())
        if exhibitDataB then
            exhibitBuilderA:SetRootParent(IBoxB:GetBoxGameObject(),true)
            exhibitBuilderB:SetRootParent(IBoxA:GetBoxGameObject(),true)
            IBoxAInfo:SetDepositServerID(exhibitDataB:GetServerID())
        else
            exhibitBuilderA:SetRootParent(IBoxB:GetBoxGameObject(),true)
            IBoxAInfo:SetDepositServerID(-1)
        end
    end
end

function PersonalHomeView:ExhibitAssembleOver()
    if PersonalHomeDataManager:Get():GetPersonalHomeData().rid == PlayerDataManager:Get():GetPlayerRID() then
        HomeSceneCarMeshHelper:Get():LoadAllCar(SceneChangeID.PersonalHome)
        if self.TipsEffect then
           self.coroutine1= cs_coroutine.start(function()
                local carCount=#(CarDataManager:Get():GetCarList())
                for i = 1, carCount do
                    coroutine.yield(CS.UnityEngine.WaitForSeconds(0.1))
                    local per= 0.14*i+ (1-carCount*0.14)
                    PersonalHomeDataManager:Get():UpdatePersonalLoading(per)
                end
                coroutine.yield()
                CarBuilderManager:Get():RemoveBuildMask()
                PersonalHomeDataManager:Get():UpdateLoadingFinish()
                self.TipsEffect:SetActive(false)
                coroutine.yield(CS.UnityEngine.WaitForSeconds(3))
                self.TipsEffect:SetActive(false)
            end)
        end
    else
        local endFun
        if self.TipsEffect then
            endFun=function()
                CarBuilderManager:Get():RemoveBuildMask()
                PersonalHomeDataManager:Get():UpdateLoadingFinish()
                self.coroutine2= cs_coroutine.start(function()
                    coroutine.yield(CS.UnityEngine.WaitForSeconds(0.2))
                    self.TipsEffect:SetActive(false)
                    coroutine.yield(CS.UnityEngine.WaitForSeconds(3))
                    self.TipsEffect:SetActive(false)
                end)
            end
        end
        local count,basePer =0 , (10-#PersonalHomeDataManager:Get().curInfo.buildParamDic*1.4)/10
        local changeFunc=function()
            count = count+1
            PersonalHomeDataManager:Get():UpdatePersonalLoading(count*0.15+basePer)
        end
        PersonalHomeDataManager:Get():BuilderOtherPlayerCars(endFun,changeFunc)
    end
end

function PersonalHomeView:OnOpen()
    self.cameraPoint=1
    self.curIBox=nil
    CommonHelper:CSGameObjectSetActive(self.BtnStorageBag.gameObject, false)
    CS.PersonalHomeBox.GlobalActive=self.cameraPoint~=1
    CommonHelper:SetText("###PointCountText", self.BtnCameraChange.gameObject,self.cameraPoint)
    --PersonalHomeHelper.SetIsCanOperationSign(false)
    self.OnClickLastTime=-1
end

function PersonalHomeView:OnOpenAnimEnd()
end

function PersonalHomeView:OnClose()
    self:OnCloseClear()
end
function PersonalHomeView:OnAutoClose()
    self:OnCloseClear()
end
function PersonalHomeView:Clear()
    self.curIBox=nil
    if self.coroutine1 then
        cs_coroutine.stop(self.coroutine1)
        self.coroutine1=nil
    end
    if self.coroutine2 then
        cs_coroutine.stop(self.coroutine2)
        self.coroutine2=nil
    end
end

function PersonalHomeView:OnCloseClear()
   PersonalHomeDataManager:Get():OnCloseClear()
    HomeSceneCarMeshHelper:Get():ClearCache()
end




